10	/// `Lexer` trait defines the necessary methods a lexer must implement.
11	/// Lexer is responsible for dividing the source code into meaningful parsing units (kinds).
12	pub trait Lexer<'src> {
13	    /// The kind of the newline
14	    const NEWLINE: Self::Kind;
15	
16	    /// The kind of the space
17	    const WHITESPACE: Self::Kind;
18	
19	    /// A kind of syntax, as identified by the lexer.
20	    type Kind: SyntaxKind;
21	    /// The specific context in which the lexer operates.
22	    type LexContext: LexContext + Default;
23	    /// The special context for re-lexing the kinds.
24	    type ReLexContext;
25	
26	    /// Returns the entire source code that lexer needs to tokenize.
27	    fn source(&self) -> &'src str;
28	
29	    /// Returns the syntax kind of the current kind.
30	    fn current(&self) -> Self::Kind;
31	
32	    /// Provides the text range of the current kind.
33	    fn current_range(&self) -> TextRange {
34	        TextRange::new(self.current_start(), TextSize::from(self.position() as u32))
35	    }
36	
37	    /// Byte offset of the current token from the start of the source
38	    /// The range of the current token can be computed by `self.position - self.current_start`
39	    fn current_start(&self) -> TextSize;
40	
41	    /// Tokenizes the next kind into a single coherent token within the given lexing context.
42	    fn next_token(&mut self, context: Self::LexContext) -> Self::Kind;
43	
44	    /// Returns `true` if the current kind is preceded by a line break.
45	    fn has_preceding_line_break(&self) -> bool;
46	
47	    /// Returns `true` if the current kind is preceded by whitespace trivia.
48	    fn has_preceding_whitespace(&self) -> bool {
49	        false
50	    }
51	
52	    /// Returns if the current kind is an identifier that includes a unicode escape sequence (`\u...`).
53	    fn has_unicode_escape(&self) -> bool;
54	
55	    /// Restores lexer to the state of a previously created checkpoint.
56	    fn rewind(&mut self, checkpoint: LexerCheckpoint<Self::Kind>);
57	
58	    /// Returns any parsing diagnostics upon finishing lexing all kinds.
59	    fn finish(self) -> Vec<ParseDiagnostic>;
60	
61	    /// Provides flags related to the current kind, containing the meta-information about the kind.
62	    fn current_flags(&self) -> TokenFlags {
63	        TokenFlags::empty()
64	    }
65	
66	    /// Returns the current position
67	    fn position(&self) -> usize;
68	
69	    fn push_diagnostic(&mut self, diagnostic: ParseDiagnostic);
70	
