132	    p: &mut MarkdownParser,
133	    use_virtual_line_start: bool,
134	) -> Option<bool> {
135	    let saved_virtual = save_virtual_line_start_if_needed(p, use_virtual_line_start);
136	
137	    emit_quote_pre_marker_indents(p);
138	
139	    restore_virtual_line_start_if_needed(p, saved_virtual);
140	
