21	pub fn run(test_case: &str, _snapshot_name: &str, test_directory: &str, outcome_str: &str) {
22	    let outcome = match outcome_str {
23	        "ok" => ExpectedOutcome::Pass,
24	        "error" => ExpectedOutcome::Fail,
25	        "undefined" => ExpectedOutcome::Undefined,
26	        _ => panic!("Invalid expected outcome {outcome_str}"),
27	    };
28	
29	    let test_case_path = Path::new(test_case);
30	
31	    let file_name = test_case_path
32	        .file_name()
33	        .expect("Expected test to have a file name")
34	        .to_str()
35	        .expect("File name to be valid UTF8");
36	
37	    let content = fs::read_to_string(test_case_path)
38	        .expect("Expected test path to be a readable file in UTF8 encoding");
39	
40	    let parsed = parse_markdown(&content);
41	    validate_eof_token(parsed.syntax());
42	
43	    let formatted_ast = format!("{:#?}", parsed.tree());
44	
45	    let mut snapshot = String::new();
46	    writeln!(snapshot, "\n## Input\n\n```\n{content}\n```\n\n").unwrap();
47	
48	    writeln!(
49	        snapshot,
50	        r#"## AST
51	
52	```
53	{formatted_ast}
54	```
55	
56	## CST
57	
58	```
59	{:#?}
60	```
61	"#,
62	        parsed.syntax()
63	    )
64	    .unwrap();
65	
66	    let diagnostics = parsed.diagnostics();
67	    if !diagnostics.is_empty() {
68	        let mut diagnostics_buffer = termcolor::Buffer::no_color();
69	
70	        let termcolor = &mut Termcolor(&mut diagnostics_buffer);
71	        let mut formatter = Formatter::new(termcolor);
72	
73	        for diagnostic in diagnostics {
74	            let error = diagnostic
75	                .clone()
76	                .with_file_path(file_name)
77	                .with_file_source_code(&content);
78	
79	            formatter
80	                .write_markup(markup! {
81	                    {PrintDiagnostic::verbose(&error)}
82	                })
83	                .expect("failed to emit diagnostic");
84	        }
85	
86	        let formatted_diagnostics =
87	            std::str::from_utf8(diagnostics_buffer.as_slice()).expect("non utf8 in error buffer");
88	
89	        if matches!(outcome, ExpectedOutcome::Pass) {
90	            panic!(
91	                "Expected no errors to be present in a test case that is expected to pass but the following diagnostics are present:\n{formatted_diagnostics}"
92	            )
93	        }
94	
95	        writeln!(snapshot, "## Diagnostics\n\n```").unwrap();
96	        snapshot.write_str(formatted_diagnostics).unwrap();
97	
98	        writeln!(snapshot, "```\n").unwrap();
99	    }
100	
101	    match outcome {
102	        ExpectedOutcome::Pass => {
103	            let missing_required = formatted_ast.contains("missing (required)");
104	            if missing_required
105	                || parsed
106	                    .syntax()
107	                    .descendants()
108	                    .any(|node| node.kind().is_bogus())
109	            {
110	                panic!(
111	                    "Parsed tree of a 'OK' test case should not contain any missing required children or bogus nodes: \n {formatted_ast:#?} \n\n {formatted_ast}"
112	                );
113	            }
114	
115	            let syntax = parsed.syntax();
116	            if has_bogus_nodes_or_empty_slots(&syntax) {
117	                panic!("modified tree has bogus nodes or empty slots:\n{syntax:#?} \n\n {syntax}")
118	            }
119	
120	            // Optional reference HTML comparison: if a .html sidecar exists,
121	            // render via document_to_html and compare against the reference.
122	            let html_path = test_case_path.with_extension("html");
123	            if html_path.exists() {
124	                let doc = MdDocument::cast(parsed.syntax()).unwrap_or_else(|| {
125	                    panic!("Failed to cast parsed output to MdDocument for {file_name}. Check that the .md test input is syntactically valid and re-run with `cargo t -p biome_markdown_parser` to see parser diagnostics.")
126	                });
127	                let actual = document_to_html(
128	                    &doc,
129	                    parsed.list_tightness(),
130	                    parsed.list_item_indents(),
131	                    parsed.quote_indents(),
132	                );
133	                let expected =
134	                    fs::read_to_string(&html_path).expect("Failed to read reference HTML file");
135	                let actual_normalized = normalize_html(&actual);
136	                let expected_normalized = normalize_html(&expected);
137	                similar_asserts::assert_eq!(
138	                    expected_normalized,
139	                    actual_normalized,
140	                    "HTML mismatch for {file_name}. Update the .html sidecar or fix the renderer in document_to_html()."
141	                );
142	            }
143	
144	            // Structural invariant: MdContinuationIndent children must all be MdIndentToken.
145	            for node in parsed.syntax().descendants() {
146	                if node.kind() == MarkdownSyntaxKind::MD_CONTINUATION_INDENT {
147	                    for child in node.children() {
148	                        if child.kind() == MarkdownSyntaxKind::MD_INDENT_TOKEN_LIST {
149	                            for token_node in child.children() {
150	                                assert_eq!(
151	                                    token_node.kind(),
152	                                    MarkdownSyntaxKind::MD_INDENT_TOKEN,
153	                                    "Structural invariant violation in {file_name}: MdContinuationIndent contains {:?} instead of MD_INDENT_TOKEN. Check the parser's continuation indent logic in syntax/list.rs.",
154	                                    token_node.kind()
155	                                );
156	                            }
157	                        }
158	                    }
159	                }
160	            }
161	
162	            // Structural invariant: MdHeader inside list items must have a present indent field.
163	            for node in parsed.syntax().descendants() {
164	                if node.kind() == MarkdownSyntaxKind::MD_HEADER {
