183	            }
184	        }
185	        _ => {}
186	    }
187	
188	    insta::with_settings!({
189	        prepend_module_to_snapshot => false,
190	        snapshot_path => &test_directory,
191	    }, {
192	        insta::assert_snapshot!(file_name, snapshot);
193	    })
