35	/// Parse markdown source code with custom options and a node cache.
36	pub fn parse_markdown_with_cache(
37	    source: &str,
38	    cache: &mut NodeCache,
39	    options: MarkdownParserOptions,
40	) -> MarkdownParse {
41	    let link_definitions =
42	        link_reference::collect_link_reference_definitions(source, options.clone());
43	    let mut parser = MarkdownParser::new(source, options);
44	    parser.set_link_reference_definitions(link_definitions);
45	
46	    parse_document(&mut parser);
47	
48	    let (events, diagnostics, trivia, list_tightness, list_item_indents, quote_indents) =
49	        parser.finish();
50	
51	    let mut tree_sink = MarkdownLosslessTreeSink::with_cache(source, &trivia, cache);
52	    biome_parser::event::process(&mut tree_sink, events, diagnostics);
53	    let (green, diagnostics) = tree_sink.finish();
54	
55	    MarkdownParse::new(
56	        green,
57	        diagnostics,
58	        list_tightness,
59	        list_item_indents,
60	        quote_indents,
