+/// because they share continuation behavior.
+pub(crate) fn is_paragraph_like(kind: biome_markdown_syntax::MarkdownSyntaxKind) -> bool {
+    matches!(kind, MD_PARAGRAPH | MD_SETEXT_HEADER)
+}
+
+pub(crate) fn parse_any_block_with_indent_code_policy(
+    p: &mut MarkdownParser,
+    allow_indent_code_block: bool,
+) -> ParsedSyntax {
+    let start = p.cur_range().start();
+    // Handle standalone NEWLINE tokens as MdNewline nodes.
+    // This prevents inter-block NEWLINEs from becoming "newline-only paragraphs".
+    if p.at(NEWLINE) {
+        if p.at_blank_line() {
+            p.state_mut().link_reference_definition_continuation = false;
+        }
+        let m = p.start();
+        p.bump(NEWLINE);
+        return Present(m.complete(p, MD_NEWLINE));
+    }
+    if at_blank_line_start(p) {
+        p.state_mut().link_reference_definition_continuation = false;
+        // Consume blank-line whitespace as whitespace trivia (structural).
+        while p.at(MD_TEXTUAL_LITERAL) {
+            let text = p.cur_text();
+            if text == " " || text == "\t" {
+                p.consume_as_whitespace_trivia();
+            } else {
+                break;
+            }
+        }
+        if p.at(NEWLINE) {
+            let m = p.start();
+            p.bump(NEWLINE);
+            return Present(m.complete(p, MD_NEWLINE));
+        }
+        // Blank line with no trailing newline (e.g., end of file)
+        return Absent;
+    }
+
+    let allow_indent_code_block =
+        allow_indent_code_block && !p.state().link_reference_definition_continuation;
+
+    let parsed = if allow_indent_code_block && at_indent_code_block(p) {
+        parse_indent_code_block(p)
+    } else if at_fenced_code_block(p) {
+        parse_fenced_code_block(p)
+    } else if line_starts_with_fence(p) {
+        parse_fenced_code_block_force(p)
+    } else if let Some(range) = backtick_info_violation(p) {
+        // Backtick-fence info strings cannot contain backticks (CommonMark §4.5);
+        // emit a diagnostic before delegating to paragraph parsing.
+        p.error(parse_error::info_string_contains_backtick(p, range));
+        parse_paragraph(p)
+    } else if at_thematic_break_block(p) {
+        let break_block = try_parse(p, |p| {
+            let break_block = parse_thematic_break_block(p);
+            if break_block.is_absent() {
+                return Err(());
+            }
+            Ok(break_block)
+        });
+        if let Ok(parsed) = break_block {
+            parsed
+        } else {
+            parse_paragraph(p)
+        }
+    } else if at_header(p) {
+        // Check for too many hashes BEFORE try_parse (which would lose diagnostics on rewind)
+        let too_many = check_too_many_hashes(p);
+        let header_result = try_parse(p, |p| {
+            let header = parse_header(p);
+            if header.is_absent() {
+                return Err(());
+            }
+            Ok(header)
+        });
+        if let Ok(parsed) = header_result {
+            parsed
+        } else {
+            // Emit diagnostic for too many hashes (outside try_parse to persist)
+            if let Some((range, count)) = too_many {
+                p.error(parse_error::too_many_hashes(p, range, count));
+            }
+            // Not a valid header, parse as paragraph
+            parse_paragraph(p)
+        }
+    } else if at_quote(p) {
+        parse_quote(p)
+    } else if at_bullet_list_item(p) {
+        parse_bullet_list_item(p)
+    } else if at_order_list_item(p) || at_order_list_item_textual(p) {
+        // After a link reference definition with no intervening blank line,
+        // CommonMark treats the next line as paragraph continuation unless it
+        // begins a paragraph-interrupting block. Ordered lists with a starting
+        // number other than 1 cannot interrupt a paragraph (§5.2), so fall
+        // back to paragraph parsing.
+        if p.state().link_reference_definition_continuation
+            && p.state().list_nesting_depth == 0
+            && !is_ordered_list_starts_with_one(p)
+        {
+            parse_paragraph(p)
+        } else {
+            let forced = if !at_order_list_item(p) && at_order_list_item_textual(p) {
+                p.set_force_ordered_list_marker(true);
+                p.force_relex_regular();
+                true
+            } else {
+                false
+            };
+            let parsed = parse_order_list_item(p);
+            if forced {
+                p.set_force_ordered_list_marker(false);
+            }
+            if parsed.is_absent() {
+                parse_paragraph(p)
+            } else {
+                parsed
+            }
+        }
+    } else if at_html_block(p) {
+        parse_html_block(p)
+    } else if at_link_block(p) {
+        // Try to parse as link reference definition
+        // Use try_parse to fall back to paragraph if not a valid definition
+        let link_result = try_parse(p, |p| {
+            let link = parse_link_block(p);
+            if link.is_absent() {
+                return Err(());
+            }
+            Ok(link)
+        });
+        if let Ok(parsed) = link_result {
+            p.state_mut().link_reference_definition_continuation = true;
+            if link_reference_definition_before_dash_thematic_break(p) {
+                Present(parse_empty_paragraph(p))
+            } else {
+                parsed
+            }
+        } else {
+            parse_paragraph(p)
+        }
+    } else if at_block_interrupt(p) {
+        // We see a block interrupt but didn't match a concrete block above.
+        // This can happen when list item indentation is still active.
+        if at_bullet_list_item_at_any_indent(p) {
+            let prev_required = p.state().list_item_required_indent;
+            let prev_virtual = p.state().virtual_line_start;
+            p.state_mut().list_item_required_indent = 0;
+            p.state_mut().virtual_line_start = Some(p.cur_range().start());
+            let parsed = parse_bullet_list_item(p);
+            p.state_mut().list_item_required_indent = prev_required;
+            p.state_mut().virtual_line_start = prev_virtual;
+            if parsed.is_present() {
+                parsed
+            } else {
+                parse_paragraph(p)
+            }
+        } else if at_order_list_item_at_any_indent(p) {
+            let prev_required = p.state().list_item_required_indent;
+            let prev_virtual = p.state().virtual_line_start;
+            p.state_mut().list_item_required_indent = 0;
+            p.state_mut().virtual_line_start = Some(p.cur_range().start());
+            let parsed = parse_order_list_item(p);
+            p.state_mut().list_item_required_indent = prev_required;
+            p.state_mut().virtual_line_start = prev_virtual;
+            if parsed.is_present() {
+                parsed
+            } else {
+                parse_paragraph(p)
+            }
+        } else {
+            parse_paragraph(p)
+        }
+    } else {
+        // Default fallback: parse as paragraph
+        parse_paragraph(p)
+    };
+
+    if start == p.cur_range().start() {
+        let range = p.cur_range();
+        p.error(parse_error::parse_any_block_no_progress(p, range));
+        if !p.at(T![EOF]) {
+            p.bump_any();
+        }
+        return Absent;
+    }
+
+    if let Present(marker) = &parsed
+        && marker.kind(p) != MD_LINK_REFERENCE_DEFINITION
+    {
+        p.state_mut().link_reference_definition_continuation = false;
+    }
+
+    parsed
+}
+
+pub(crate) fn with_virtual_line_start<F, R>(p: &mut MarkdownParser, start: TextSize, op: F) -> R
+where
+    F: FnOnce(&mut MarkdownParser) -> R,
+{
+    let prev_virtual = p.state().virtual_line_start;
+    p.state_mut().virtual_line_start = Some(start);
+    let result = op(p);
+    p.state_mut().virtual_line_start = prev_virtual;
+    result
+}
+
+enum QuoteBreakKind {
+    None,
+    SetextUnderline,
+    Other,
+}
+
+/// Check if we're at an indented code block (4+ spaces of indentation).
+///
+/// Uses `line_start_leading_indent()` to correctly handle indentation when NEWLINE
+/// tokens are explicit (not trivia).
+pub(crate) fn at_indent_code_block(p: &mut MarkdownParser) -> bool {
+    if !p.at_line_start() {
+        return false;
+    }
+
+    if at_blank_line_start(p) {
+        return false;
+    }
+
+    let indent = p.line_start_leading_indent();
+    let required_indent = p.state().list_item_required_indent;
+
+    // Inside a list item, we need 4 spaces BEYOND the list item's required indent.
+    // e.g., if list item requires 2 spaces, code block needs 2 + 4 = 6 spaces.
+    // Outside a list item (required_indent == 0), we need just 4 spaces.
+    let effective_indent = indent.saturating_sub(required_indent);
+    effective_indent >= INDENT_CODE_BLOCK_SPACES
+}
+
+/// Parse an indented code block.
+///
+/// Grammar: MdIndentCodeBlock = content: MdInlineItemList
+///
+/// An indented code block consists of one or more lines with 4+ spaces
+/// of indentation. The indentation is tracked in trivia.
+///
+/// # NEWLINE Handling
+///
+/// NEWLINE is an explicit token. We consume tokens until NEWLINE,
+/// then check if the next line has proper indentation.
+pub(crate) fn parse_indent_code_block(p: &mut MarkdownParser) -> ParsedSyntax {
+    if !at_indent_code_block(p) {
+        return Absent;
+    }
+
+    let m = p.start();
+    let content = p.start();
+
+    // Parse content while we're at indented lines, including interior blank lines.
+    loop {
+        if p.at(T![EOF]) {
+            break;
+        }
+
+        // Always include NEWLINE tokens in code content
+        if p.at(NEWLINE) {
+            if newline_is_blank_line(p) && !has_following_indented_code_line(p) {
+                break;
+            }
+            let text_m = p.start();
+            p.bump_remap(MD_TEXTUAL_LITERAL);
+            text_m.complete(p, MD_TEXTUAL);
+            p.set_virtual_line_start();
+            continue;
+        }
+
+        if p.at_line_start() {
+            if at_blank_line_start(p) {
+                if has_following_indented_code_line(p) {
+                    consume_blank_line(p);
+                    continue;
+                }
+                break;
+            } else if !at_indent_code_block(p) {
+                break;
+            }
+            if p.state().list_item_required_indent == 0 {
+                consume_indent_prefix(p, INDENT_CODE_BLOCK_SPACES);
+            }
+        }
+
+        // Consume token as code content. The content is literal text:
+        // consume the whole rest of the line as one token instead of one
+        // token per character group.
+        p.re_lex(MarkdownReLexContext::CodeInfoString);
+        let text_m = p.start();
+        p.bump_remap(MD_TEXTUAL_LITERAL);
+        text_m.complete(p, MD_TEXTUAL);
+    }
+
+    content.complete(p, MD_INLINE_ITEM_LIST);
+    Present(m.complete(p, MD_INDENT_CODE_BLOCK))
+}
+
+fn has_following_indented_code_line(p: &mut MarkdownParser) -> bool {
+    p.lookahead(|p| {
+        while p.at_line_start() && at_blank_line_start(p) {
+            while p.at(MD_TEXTUAL_LITERAL) {
+                let text = p.cur_text();
+                if text == " " || text == "\t" {
+                    p.bump(MD_TEXTUAL_LITERAL);
+                } else {
+                    break;
+                }
+            }
+
+            if p.at(NEWLINE) {
+                p.bump(NEWLINE);
+            } else {
+                break;
+            }
+        }
+
+        at_indent_code_block(p)
+    })
+}
+
+fn newline_is_blank_line(p: &MarkdownParser) -> bool {
+    // Token stream doesn't expose the prior byte, so read source to detect CR/LF.
+    let start: usize = p.cur_range().start().into();
+    if start == 0 {
+        return true;
+    }
+
+    let source = p.source().source_text();
+    let prev = source.as_bytes()[start - 1];
+    prev == b'\n' || prev == b'\r'
+}
+
+/// Check if the current line is blank (lookahead only).
+fn consume_indent_prefix(p: &mut MarkdownParser, indent: usize) {
+    if indent == 0 {
+        return;
+    }
+
+    // Indentation arrives as one whitespace token per character; measure the
+    // run on the source and consume it as a single MdIndentToken. A tab that
+    // starts below the budget is included even when its width overshoots it.
+    if p.at(MD_TEXTUAL_LITERAL) {
+        let mut consumed = 0usize;
+        let mut len = 0usize;
+        for byte in p.source_after_current().bytes() {
+            if consumed >= indent {
+                break;
+            }
+            match byte {
+                b' ' => consumed += 1,
+                b'\t' => consumed += TAB_STOP_SPACES,
+                _ => break,
+            }
+            len += 1;
+        }
+
+        if len > 0 {
+            let end = p.cur_range().start() + TextSize::from(len as u32);
+            p.emit_span_as(end, MD_INDENT_CHAR, MD_INDENT_TOKEN);
+        }
+    }
+}
+
+/// Consume exactly `indent` columns of leading whitespace at line start.
+fn at_blank_line_start(p: &mut MarkdownParser) -> bool {
+    if !p.at_line_start() {
+        return false;
+    }
+
+    p.lookahead(|p| {
+        while p.at(MD_TEXTUAL_LITERAL) {
+            let text = p.cur_text();
+            if text == " " || text == "\t" {
+                p.bump(MD_TEXTUAL_LITERAL);
+            } else {
+                break;
+            }
+        }
+
+        p.at(NEWLINE) || p.at(T![EOF])
+    })
+}
+
+fn consume_blank_line(p: &mut MarkdownParser) {
+    // Consume blank-line whitespace as whitespace trivia (structural).
+    while p.at(MD_TEXTUAL_LITERAL) {
+        let text = p.cur_text();
+        if text == " " || text == "\t" {
+            p.consume_as_whitespace_trivia();
+        } else {
+            break;
+        }
+    }
+
+    if p.at(NEWLINE) {
+        let text_m = p.start();
+        p.bump_remap(MD_TEXTUAL_LITERAL);
+        text_m.complete(p, MD_TEXTUAL);
+    }
+}
+
+/// Parse a paragraph block, or a setext heading if followed by an underline.
+///
+/// A paragraph is a sequence of non-blank lines that cannot be interpreted as
+/// other kinds of blocks. The paragraph ends at a blank line or EOF.
+///
+/// If the paragraph is followed by a setext heading underline (=== or ---),
+/// it becomes a setext heading instead.
+///
+/// Grammar: MdParagraph = list: MdInlineItemList
+/// Grammar: MdSetextHeader = content: MdInlineItemList underline: 'md_setext_underline_literal'
+///
+/// Hard line breaks are inline items inside `list` (`AnyMdInline::MdHardLine`),
+/// not a paragraph-level slot.
+pub(crate) fn parse_paragraph(p: &mut MarkdownParser) -> ParsedSyntax {
+    let m = p.start();
+
+    let inline_start: usize = p.cur_range().start().into();
+    parse_inline_item_list(p);
+    let inline_end: usize = p.cur_range().start().into();
+
+    let has_inline_content = inline_has_non_whitespace(p, inline_start, inline_end);
+    let allow_setext = has_inline_content && allow_setext_heading(p);
+
+    // Check if this paragraph is followed by a setext heading underline
+    // MD_SETEXT_UNDERLINE_LITERAL is for `=` underlines
+    // MD_THEMATIC_BREAK_LITERAL with only `-` is also a setext underline (H2)
+    let completed = if allow_setext && p.at(MD_SETEXT_UNDERLINE_LITERAL) {
+        let indent = real_line_indent_from_source(p);
+        if indent < INDENT_CODE_BLOCK_SPACES {
+            // This is a setext heading (H1 with `=`) - consume the underline
+            p.bump(MD_SETEXT_UNDERLINE_LITERAL);
+            m.complete(p, MD_SETEXT_HEADER)
+        } else {
+            // 4+ spaces of indent: not a setext underline (CommonMark §4.3)
+            m.complete(p, MD_PARAGRAPH)
+        }
+    } else if allow_setext && p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break(p) {
+        let indent = real_line_indent_from_source(p);
+        if indent < INDENT_CODE_BLOCK_SPACES {
+            // This is a setext heading (H2 with `-`) - remap token and consume
+            p.bump_remap(MD_SETEXT_UNDERLINE_LITERAL);
+            m.complete(p, MD_SETEXT_HEADER)
+        } else {
+            // 4+ spaces of indent: not a setext underline (CommonMark §4.3)
+            m.complete(p, MD_PARAGRAPH)
+        }
+    } else {
+        m.complete(p, MD_PARAGRAPH)
+    };
+    Present(completed)
+}
+
+pub(crate) fn parse_empty_paragraph(p: &mut MarkdownParser) -> CompletedMarker {
+    let paragraph = p.start();
+    let list = p.start();
+    list.complete(p, MD_INLINE_ITEM_LIST);
+    paragraph.complete(p, MD_PARAGRAPH)
+}
+
+fn link_reference_definition_before_dash_thematic_break(p: &mut MarkdownParser) -> bool {
+    if !p.at(NEWLINE) || p.at_blank_line() {
+        return false;
+    }
+
+    p.lookahead(|p| {
+        p.bump(NEWLINE);
+
+        while p.at(MD_TEXTUAL_LITERAL) {
+            let text = p.cur_text();
+            if text == " " || text == "\t" {
+                p.bump(MD_TEXTUAL_LITERAL);
+            } else {
+                break;
+            }
+        }
+
+        p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break(p)
+    })
+}
+
+fn inline_has_non_whitespace(p: &MarkdownParser, start: usize, end: usize) -> bool {
+    if end <= start {
+        return false;
+    }
+
+    let source = p.source().source_text();
+    if end > source.len() {
+        return false;
+    }
+
+    !source[start..end]
+        .trim_matches(|c: char| matches!(c, ' ' | '\t' | '\r' | '\n'))
+        .is_empty()
+}
+
+/// Check if a thematic break text contains only dashes (used for setext H2 detection).
+pub(crate) fn is_dash_only_thematic_break_text(text: &str) -> bool {
+    !text.is_empty() && text.trim().chars().all(|c| c == '-')
+}
+
+/// Returns `Some(indent_bytes)` if the current line is a setext underline.
+///
+/// Call this after consuming `NEWLINE`. It skips up to 3 columns of leading
+/// whitespace, then checks for a setext underline token or a dash-only thematic
+/// break token. The returned byte count covers only the skipped whitespace.
+pub(crate) fn at_setext_underline_after_newline(p: &mut MarkdownParser) -> Option<usize> {
+    let mut columns = 0;
+    let mut bytes_consumed = 0;
+    while columns < INDENT_CODE_BLOCK_SPACES
+        && p.at(MD_TEXTUAL_LITERAL)
+        && p.cur_text().chars().all(|c| c == ' ' || c == '\t')
+    {
+        for c in p.cur_text().chars() {
+            match c {
+                ' ' => columns += 1,
+                '\t' => columns += TAB_STOP_SPACES - (columns % TAB_STOP_SPACES),
+                _ => {}
+            }
+        }
+        bytes_consumed += p.cur_text().len();
+        p.bump(MD_TEXTUAL_LITERAL);
+    }
+    if columns >= INDENT_CODE_BLOCK_SPACES {
+        return None;
+    }
+    let is_setext = p.at(MD_SETEXT_UNDERLINE_LITERAL)
+        || (p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break_text(p.cur_text()));
+    if is_setext {
+        Some(bytes_consumed)
+    } else {
+        None
+    }
+}
+
+/// Token-based check: does an inline span of `byte_len` bytes cross a setext underline?
+///
+/// Walks tokens via lookahead. At each NEWLINE, delegates to
+/// [`at_setext_underline_after_newline`] — the same detection used by
+/// `has_matching_code_span_closer` and `parse_inline_item_list`.
+pub(crate) fn inline_span_crosses_setext(p: &mut MarkdownParser, byte_len: usize) -> bool {
+    p.lookahead(|p| {
+        let mut remaining = byte_len;
+        loop {
+            if remaining == 0 || p.at(T![EOF]) {
+                return false;
+            }
+            if p.at(NEWLINE) {
+                let nl_len = p.cur_text().len();
+                if nl_len > remaining {
+                    return false;
+                }
+                remaining -= nl_len;
+                p.bump(NEWLINE);
+                if let Some(ws_bytes) = at_setext_underline_after_newline(p) {
+                    // Only flag if the whitespace consumed is still within our span
+                    return ws_bytes <= remaining;
+                }
+                continue;
+            }
+            let tok_len = p.cur_text().len();
+            if tok_len > remaining {
+                return false;
+            }
+            remaining -= tok_len;
+            p.bump_any();
+        }
+    })
+}
+
+/// Check if the current thematic break token contains only dashes.
+/// This is used to detect H2 setext underlines.
+fn is_dash_only_thematic_break(p: &MarkdownParser) -> bool {
+    is_dash_only_thematic_break_text(p.cur_text())
+}
+
+fn allow_setext_heading(p: &MarkdownParser) -> bool {
+    let required_indent = p.state().list_item_required_indent;
+    if required_indent > 0 {
+        // Compute real indent from source text, since leading whitespace
+        // may have been consumed as trivia in list item context.
+        let indent = real_line_indent_from_source(p);
+        if indent < required_indent {
+            return false;
+        }
+    }
+
+    if p.state().list_item_required_indent > 0 && p.at(MD_SETEXT_UNDERLINE_LITERAL) {
+        let text = p.cur_text().trim_matches(|c| c == ' ' || c == '\t');
+        if text == "-" {
+            return false;
+        }
+    }
+
+    let depth = p.state().block_quote_depth;
+    if depth == 0 {
+        return true;
+    }
+
+    line_has_quote_prefix_at_current(p, depth)
+}
+
+/// Compute the real leading indent of the current line from source text.
+/// This is needed because leading whitespace may have been consumed as trivia
+/// in list item context, making `line_start_leading_indent()` return 0.
+/// Token-based lookahead cannot recover the original column once trivia is skipped.
+fn real_line_indent_from_source(p: &MarkdownParser) -> usize {
+    let source = p.source().source_text();
+    let pos: usize = p.cur_range().start().into();
+
+    // Find the start of the current line
+    let line_start = source[..pos].rfind('\n').map_or(0, |i| i + 1);
+
+    // Count leading whitespace columns on this line
+    let mut column = 0;
+    for c in source[line_start..].chars() {
+        match c {
+            ' ' => column += 1,
+            '\t' => column += TAB_STOP_SPACES - (column % TAB_STOP_SPACES),
+            _ => break,
+        }
+    }
+    column
+}
+
+fn classify_quote_break_after_newline(
+    p: &mut MarkdownParser,
+    quote_depth: usize,
+) -> QuoteBreakKind {
+    p.lookahead(|p| {
+        consume_quote_prefix_without_virtual(p, quote_depth);
+        // CommonMark §4.3: a setext underline must sit in the same container
+        // as the paragraph it underlines. When the paragraph is inside a list
+        // item and the residual indent after the `>` prefix is below the
+        // list's required indent, the dash line cannot be a setext underline —
+        // it is a thematic break that ends the list. Reporting it as `Other`
+        // (vs `SetextUnderline`) keeps the `>` prefix unconsumed so the outer
+        // blockquote can re-process the line.
+        let required_indent = p.state().list_item_required_indent;
+        let residual_indent = leading_indent_at_current(p);
+        let underline_in_container = required_indent == 0 || residual_indent >= required_indent;
+        with_virtual_line_start(p, p.cur_range().start(), |p| {
+            // Re-lex at line start so the lexer produces block-level tokens
+            // (e.g. MD_THEMATIC_BREAK_LITERAL for `---`) instead of MINUS.
+            p.force_relex_at_line_start();
+            let at_setext = p.at(MD_SETEXT_UNDERLINE_LITERAL)
+                || (p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break(p));
+            if at_setext && underline_in_container {
+                return QuoteBreakKind::SetextUnderline;
+            }
+            if at_setext || at_block_interrupt(p) || textual_looks_like_list_marker(p) {
+                return QuoteBreakKind::Other;
+            }
+            // Tab between `>` and a block-level marker (e.g. `> \t- nested`)
+            // leaves the marker token mid-line in the buffer, so the direct
+            // checks miss it. Only enter the lookahead retry when the current
+            // token is a whitespace-only textual run that contains a tab —
+            // otherwise the original checks above are authoritative and the
+            // retry would add lookahead overhead to every quote continuation.
+            let needs_ws_retry = p.at(MD_TEXTUAL_LITERAL) && {
+                let bytes = p.cur_text().as_bytes();
+                !bytes.is_empty()
+                    && bytes.iter().all(|b| matches!(b, b' ' | b'\t'))
+                    && bytes.contains(&b'\t')
+            };
+            if !needs_ws_retry {
+                return QuoteBreakKind::None;
+            }
+            let interrupts_after_ws = p.lookahead(|p| {
+                while p.at(MD_TEXTUAL_LITERAL) {
+                    let bytes = p.cur_text().as_bytes();
+                    if bytes.is_empty() || !bytes.iter().all(|b| matches!(b, b' ' | b'\t')) {
+                        break;
+                    }
+                    p.bump(MD_TEXTUAL_LITERAL);
+                }
+                with_virtual_line_start(p, p.cur_range().start(), |p| {
+                    p.force_relex_at_line_start();
+                    at_block_interrupt(p) || textual_looks_like_list_marker(p)
+                })
+            });
+            if interrupts_after_ws {
+                QuoteBreakKind::Other
+            } else {
+                QuoteBreakKind::None
+            }
+        })
+    })
+}
+
+/// Count residual indent columns at the current parser position.
+///
+/// Used after lookahead consumes a container prefix such as `> `. This is not
+/// full line-start indent; it only measures spaces/tabs before the next block
+/// candidate without advancing the real parser.
+fn leading_indent_at_current(p: &mut MarkdownParser) -> usize {
+    p.lookahead(|p| {
+        let mut indent = 0usize;
+        while p.at(MD_TEXTUAL_LITERAL) {
+            let text = p.cur_text();
+            if text.is_empty() {
+                break;
+            }
+
+            for c in text.chars() {
+                match c {
+                    ' ' => indent += 1,
+                    '\t' => indent += TAB_STOP_SPACES - (indent % TAB_STOP_SPACES),
+                    _ => return indent,
+                }
+            }
+
+            p.bump(MD_TEXTUAL_LITERAL);
+        }
+        indent
+    })
+}
+
+/// Returns `true` when the current (no-quote-prefix) line begins a block
+/// construct strict enough to end blockquote lazy continuation.
+///
+/// CommonMark distinguishes "paragraph interrupt" rules (e.g. ordered lists
+/// must start with `1` to interrupt a paragraph) from "begins a new block"
+/// rules used for laziness. An ordered list with start > 1 still *begins a
+/// new block*, so it terminates a lazily continued blockquote even though it
+/// would not interrupt a top-level paragraph.
+fn begins_blockquote_terminating_block(p: &mut MarkdownParser) -> bool {
+    use biome_markdown_syntax::MarkdownSyntaxKind::MD_ORDERED_LIST_MARKER;
+    // The lexer can split a line into a leading whitespace token followed by
+    // the marker token (e.g. `"  "` then `"2."`), so walk past whitespace-only
+    // `MD_TEXTUAL_LITERAL` tokens via a lookahead before testing the marker.
+    p.lookahead(|p| {
+        while p.at(MD_TEXTUAL_LITERAL) {
+            let bytes = p.cur_text().as_bytes();
+            if bytes.is_empty() || !bytes.iter().all(|b| matches!(b, b' ' | b'\t')) {
+                break;
+            }
+            p.bump(MD_TEXTUAL_LITERAL);
+        }
+        let text = if p.at(MD_TEXTUAL_LITERAL) || p.at(MD_ORDERED_LIST_MARKER) {
+            p.cur_text()
+        } else {
+            return false;
+        };
+        let trimmed = text.trim_start_matches([' ', '\t']);
+        if !crate::syntax::list::textual_starts_with_ordered_marker(trimmed) {
+            return false;
+        }
+        let digit_bytes = trimmed.as_bytes();
+        let digit_len = digit_bytes
+            .iter()
+            .take_while(|b| b.is_ascii_digit())
+            .count();
+        // `1.` / `1)` is handled by the paragraph-interrupt path. Only the
+        // start > 1 case needs the broader laziness rule here. Compare the
+        // borrowed digit prefix instead of allocating a String.
+        !(digit_len == 1 && digit_bytes[0] == b'1')
+    })
+}
+
+/// Check if the current position is a paragraph break (setext underline,
+/// thematic break, fence, block interrupt, or textual list marker).
+///
+/// This shared predicate consolidates the duplicate break-condition checks
+/// in [`handle_inline_newline`] and [`inline_list_source_len`].
+fn at_paragraph_break(p: &mut MarkdownParser, has_content: bool) -> bool {
+    if has_content && p.at(MD_SETEXT_UNDERLINE_LITERAL) && allow_setext_heading(p) {
+        return true;
+    }
+    if has_content && p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break(p) {
+        return true;
+    }
+    if line_starts_with_fence(p) {
+        return true;
+    }
+    at_block_interrupt(p) || textual_looks_like_list_marker(p)
+}
+
+enum InlineNewlineAction {
+    Break,
+    Continue,
+}
+
+fn emit_inline_newline_as_text(p: &mut MarkdownParser) {
+    let text_m = p.start();
+    p.bump_remap(MD_TEXTUAL_LITERAL);
+    text_m.complete(p, MD_TEXTUAL);
+}
+
+fn is_quote_blank_line_after_newline(p: &mut MarkdownParser, quote_depth: usize) -> bool {
+    if quote_depth == 0 {
+        return false;
+    }
+
+    p.lookahead(|p| {
+        p.bump(NEWLINE);
+        is_quote_blank_line_from_current(p, quote_depth)
+    })
+}
+
+fn is_quote_blank_line_from_current(p: &mut MarkdownParser, quote_depth: usize) -> bool {
+    p.lookahead(|p| {
+        if is_quote_only_blank_line_from_source(p, quote_depth) {
+            return true;
+        }
+        if !has_quote_prefix(p, quote_depth) {
+            return false;
+        }
+        consume_quote_prefix_without_virtual(p, quote_depth);
+        while p.at(MD_TEXTUAL_LITERAL) && p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
+            p.bump(MD_TEXTUAL_LITERAL);
+        }
+        p.at(NEWLINE) || p.at(T![EOF])
+    })
+}
+
+/// Returns `true` when the quote prefix signals a block break (setext
+/// underline or other block construct), in which case the paragraph must end.
+///
+/// **Side effect**: consumes the quote prefix tokens from the parser when the
+/// line is either a continuation (`None`) or a setext underline, so that
+/// downstream consumers see the content without the leading `>` markers.
+fn break_for_quote_prefix_after_inline_newline(p: &mut MarkdownParser, quote_depth: usize) -> bool {
+    if quote_depth == 0 {
+        return false;
+    }
+
+    if has_quote_prefix(p, quote_depth) {
+        let break_kind = classify_quote_break_after_newline(p, quote_depth);
+        if matches!(break_kind, QuoteBreakKind::SetextUnderline) {
+            // Consume the quote prefix and re-lex at line start so the
+            // paragraph parser sees MD_THEMATIC_BREAK_LITERAL for `---`.
+            consume_quote_prefix(p, quote_depth);
+            p.force_relex_at_line_start();
+        }
+        match break_kind {
+            QuoteBreakKind::SetextUnderline | QuoteBreakKind::Other => return true,
+            QuoteBreakKind::None => {
+                consume_quote_prefix(p, quote_depth);
+            }
+        }
+    }
+
+    if p.at(R_ANGLE) && !has_quote_prefix(p, quote_depth) {
+        consume_partial_quote_prefix(p, quote_depth);
+    }
+
+    false
+}
+
+/// Returns `true` when the parser should break so the paragraph parser can
+/// handle a setext underline on the following line. When returning `true`,
+/// this helper also emits the indent tokens needed to expose the underline.
+///
+/// For non-list paragraphs, we still gate this on [`allow_setext_heading`]
+/// so a setext-looking line outside a block quote does not incorrectly
+/// terminate the paragraph (CommonMark example 093).
+fn break_for_setext_after_inline_newline(
+    p: &mut MarkdownParser,
+    has_content: bool,
+    required_indent: usize,
+) -> bool {
+    if !has_content {
+        return false;
+    }
+
+    if required_indent == 0 {
+        if allow_setext_heading(p)
+            && p.lookahead(|p| at_setext_underline_after_newline(p).is_some())
+        {
+            p.emit_indent_tokens(INDENT_CODE_BLOCK_SPACES);
+            return true;
+        }
+        return false;
+    }
+
+    let real_indent = real_line_indent_from_source(p);
+    if real_indent < required_indent {
+        return false;
+    }
+
+    let is_setext = p.lookahead(|p| {
+        p.skip_line_indent(required_indent);
+        at_setext_underline_after_newline(p).is_some()
+    });
+    if is_setext {
+        p.emit_indent_tokens(required_indent);
+        p.emit_indent_tokens(INDENT_CODE_BLOCK_SPACES);
+        return true;
+    }
+
+    false
+}
+
+/// Break the paragraph when the next line starts a list-interrupting
+/// block, including sibling/parent list markers whose indent is below
+/// the current item's `required_indent` (CommonMark §5.2).
+fn break_for_list_interrupt_after_inline_newline(
+    p: &mut MarkdownParser,
+    required_indent: usize,
+) -> bool {
+    if required_indent == 0 {
+        return false;
+    }
+
+    let indent = p.line_start_leading_indent();
+    if indent < required_indent && indent > p.state().list_item_marker_indent {
+        return false;
+    }
+
+    // Line sits at sibling/parent level. A list marker here ends the
+    // current paragraph (CommonMark §5.2). Tabs need the broad token-aware
+    // lookahead because `MD_TEXTUAL_LITERAL` can absorb the tab and any
+    // following marker; the non-tab path only needs to cover non-1 ordered
+    // siblings continuing an existing list.
+    if indent < required_indent {
+        if line_start_indent_contains_tab(p) {
+            return line_starts_with_list_marker_after_indent(p, indent);
+        }
+        return line_starts_with_nonone_ordered_marker_after_indent(p, indent);
+    }
+
+    let skip = indent.min(required_indent);
+    p.lookahead(|p| {
+        p.skip_line_indent(skip);
+        let prev_required = p.state().list_item_required_indent;
+        with_virtual_line_start(p, p.cur_range().start(), |p| {
+            p.state_mut().list_item_required_indent = 0;
+            let breaks = at_block_interrupt(p) || textual_looks_like_list_marker(p);
+            p.state_mut().list_item_required_indent = prev_required;
+            breaks
+        })
+    })
+}
+
+/// True if current `MD_TEXTUAL_LITERAL`'s leading space/tab run contains a tab.
+fn line_start_indent_contains_tab(p: &MarkdownParser) -> bool {
+    p.at(MD_TEXTUAL_LITERAL)
+        && p.cur_text()
+            .chars()
+            .take_while(|c| *c == ' ' || *c == '\t')
+            .any(|c| c == '\t')
+}
+
+/// Lookahead: after skipping `indent` columns of leading whitespace, does
+/// the next token begin a non-1 ordered marker followed by whitespace/EOL?
+/// Covers `parse_inline_item_list`'s blind spot (`textual_looks_like_list_marker`
+/// only matches `1.`/`1)` for ordered); `1.`/`1)` and bullets are left to the
+/// inline loop.
+fn line_starts_with_nonone_ordered_marker_after_indent(
+    p: &mut MarkdownParser,
+    indent: usize,
+) -> bool {
+    p.lookahead(|p| {
+        p.skip_line_indent(indent);
+        if p.at(MD_ORDERED_LIST_MARKER) {
+            let text = p.cur_text();
+            if text == "1." || text == "1)" {
+                return false;
+            }
+            p.bump(MD_ORDERED_LIST_MARKER);
+            return marker_followed_by_whitespace_or_eol(p);
+        }
+        if p.at(MD_TEXTUAL_LITERAL) {
+            let text = p.cur_text();
+            if text
+                .strip_prefix("1.")
+                .or_else(|| text.strip_prefix("1)"))
+                .is_some_and(|rest| rest.is_empty() || rest.starts_with([' ', '\t', '\n', '\r']))
+            {
+                return false;
+            }
+            return textual_starts_with_ordered_marker(text);
+        }
+        false
+    })
+}
+
+/// Lookahead: after skipping `indent` columns of leading whitespace, is the next
+/// token a list marker (`-`, `*`, `+`, ordered) followed by whitespace or EOL?
+/// Handles raw marker tokens and markers still folded into `MD_TEXTUAL_LITERAL`
+/// / `MD_SETEXT_UNDERLINE_LITERAL`.
+fn line_starts_with_list_marker_after_indent(p: &mut MarkdownParser, indent: usize) -> bool {
+    p.lookahead(|p| {
+        p.skip_line_indent(indent);
+
+        if p.at(T![-]) || p.at(T![*]) || p.at(T![+]) {
+            p.bump(p.cur());
+            return marker_followed_by_whitespace_or_eol(p);
+        }
+
+        if p.at(MD_SETEXT_UNDERLINE_LITERAL) {
+            let trimmed = p.cur_text().trim_matches(|c| c == ' ' || c == '\t');
+            if trimmed != "-" {
+                return false;
+            }
+            p.bump_remap(T![-]);
+            return marker_followed_by_whitespace_or_eol(p);
+        }
+
+        if p.at(MD_ORDERED_LIST_MARKER) {
+            p.bump(MD_ORDERED_LIST_MARKER);
+            return marker_followed_by_whitespace_or_eol(p);
+        }
+
+        if !p.at(MD_TEXTUAL_LITERAL) {
+            return false;
+        }
+
+        let text = p.cur_text();
+        let marker_kind = match text {
+            "-" => T![-],
+            "*" => T![*],
+            "+" => T![+],
+            _ => return textual_starts_with_ordered_marker(text),
+        };
+        p.bump_remap(marker_kind);
+        marker_followed_by_whitespace_or_eol(p)
+    })
+}
+
+/// Per CommonMark §5.2, list-item continuations emit their required indent
+/// when present; otherwise the line continues as a lazy continuation. Plain
+/// paragraphs strip up to 4 leading spaces on continuation lines.
+fn emit_inline_continuation_indent(p: &mut MarkdownParser, required_indent: usize) {
+    if required_indent > 0 {
+        let indent = p.line_start_leading_indent();
+        if indent >= required_indent {
+            p.emit_indent_tokens(required_indent);
+        }
+        return;
+    }
+
+    p.emit_indent_tokens(INDENT_CODE_BLOCK_SPACES);
+}
+
+fn handle_inline_newline(p: &mut MarkdownParser, has_content: bool) -> InlineNewlineAction {
+    if p.at_blank_line() {
+        emit_inline_newline_as_text(p);
+        return InlineNewlineAction::Break;
+    }
+
+    let quote_depth = p.state().block_quote_depth;
+    if is_quote_blank_line_after_newline(p, quote_depth) {
+        emit_inline_newline_as_text(p);
+        return InlineNewlineAction::Break;
+    }
+
+    // Not a blank line - this is a soft line break within paragraph
+    // Consume the NEWLINE as textual content (remap to MD_TEXTUAL_LITERAL)
+    emit_inline_newline_as_text(p);
+
+    handle_line_continuation(p, has_content, true)
+}
+
+/// Consume container continuation prefixes and check for block interrupts.
+///
+/// Called after a line boundary has been crossed — either a NEWLINE (via
+/// `handle_inline_newline`) or a hard line break (`MD_HARD_LINE_LITERAL`,
+/// which embeds its own newline). Handles quote prefixes, list indent,
+/// setext underlines, and other block-level constructs that can end or
+/// interrupt a paragraph.
+fn handle_line_continuation(
+    p: &mut MarkdownParser,
+    has_content: bool,
+    emit_indent_tokens: bool,
+) -> InlineNewlineAction {
+    let quote_depth = p.state().block_quote_depth;
+    let line_has_quote_prefix = quote_depth > 0 && has_quote_prefix(p, quote_depth);
+    if break_for_quote_prefix_after_inline_newline(p, quote_depth) {
+        return InlineNewlineAction::Break;
+    }
+
+    // Unprefixed continuation in a blockquote: a line that begins any new block
+    // construct (e.g. an ordered list with start > 1) ends the blockquote per
+    // CommonMark, even though such a line could not interrupt an active
+    // top-level paragraph. With a `>` prefix, normal lazy-continuation rules
+    // apply and the line stays inside the same paragraph.
+    if quote_depth > 0 && !line_has_quote_prefix && begins_blockquote_terminating_block(p) {
+        return InlineNewlineAction::Break;
+    }
+
+    let required_indent = p.state().list_item_required_indent;
+    if break_for_setext_after_inline_newline(p, has_content, required_indent) {
+        return InlineNewlineAction::Break;
+    }
+
+    if break_for_list_interrupt_after_inline_newline(p, required_indent) {
+        return InlineNewlineAction::Break;
+    }
+
+    // The invalid fence still belongs to this paragraph; only add the diagnostic.
+    if let Some(range) = backtick_info_violation(p) {
+        p.error(parse_error::info_string_contains_backtick(p, range));
+    }
+    if p.at(MD_TEXTUAL_LITERAL) {
+        let text = p.cur_text();
+        if text.starts_with("```") || text.starts_with("~~~") {
+            return InlineNewlineAction::Break;
+        }
+    }
+    if at_paragraph_break(p, has_content) {
+        return InlineNewlineAction::Break;
+    }
+
+    if emit_indent_tokens {
+        emit_inline_continuation_indent(p, required_indent);
+    }
+
+    InlineNewlineAction::Continue
+}
+
+/// Parse the inline item list within a block.
+///
+/// Grammar: MdInlineItemList = AnyMdInline*
+///
+/// Inline content continues until we hit EOF, a blank line (paragraph boundary),
+/// a setext heading underline, or a block-level construct that can interrupt
+/// paragraphs per CommonMark.
+///
+/// # NEWLINE Handling
+///
+/// NEWLINE is an explicit token (not trivia). When we hit NEWLINE:
+/// - If it's a blank line (NEWLINE + optional whitespace + NEWLINE/EOF) → stop
+/// - Otherwise it's a soft line break → consume and continue to next line
+pub(crate) fn parse_inline_item_list(p: &mut MarkdownParser) {
+    let m = p.start();
+    let prev_emphasis_context = set_inline_emphasis_context(p);
+    let quote_depth = p.state().block_quote_depth;
+    if quote_depth > 0 && p.at_line_start() && has_quote_prefix(p, quote_depth) {
+        consume_quote_prefix(p, quote_depth);
+    }
+    let inline_start: usize = p.cur_range().start().into();
+    let mut has_content = false;
+    let mut after_hard_break = false;
+
+    loop {
+        // EOF ends inline content
+        if p.at(T![EOF]) {
+            break;
+        }
+
+        // NEWLINE handling: check for blank line (paragraph boundary)
+        if p.at(NEWLINE) {
+            // After MD_HARD_LINE, a following bare NEWLINE is the blank-line separator.
+            // Container continuations do not appear as bare NEWLINE here: they start
+            // with quote/list continuation tokens first, so this only fires for
+            // paragraph breaks.
+            if after_hard_break {
+                break;
+            }
+            if matches!(
+                handle_inline_newline(p, has_content),
+                InlineNewlineAction::Break
+            ) {
+                break;
+            }
+            continue;
+        }
+
+        // Check if we're at a setext heading underline (stop for paragraph to handle)
+        // Per CommonMark §4.3, setext underlines can be indented 0-3 spaces only.
+        if has_content
+            && p.at(MD_SETEXT_UNDERLINE_LITERAL)
+            && real_line_indent_from_source(p) < INDENT_CODE_BLOCK_SPACES
+            && allow_setext_heading(p)
+        {
+            break;
+        }
+
+        // Check if we're at a thematic break that could be a setext underline
+        // (dash-only thematic breaks following paragraph content are setext H2)
+        if has_content
+            && p.at(MD_THEMATIC_BREAK_LITERAL)
+            && real_line_indent_from_source(p) < INDENT_CODE_BLOCK_SPACES
+            && is_dash_only_thematic_break(p)
+        {
+            break;
+        }
+
+        // Per CommonMark, certain block-level constructs can interrupt paragraphs
+        // without requiring a blank line. Check for these at line start.
+        if p.has_preceding_line_break() && at_block_interrupt(p) {
+            break;
+        }
+
+        // Also check for list markers in textual content (see comment above)
+        if p.has_preceding_line_break() && textual_looks_like_list_marker(p) {
+            break;
+        }
+
+        // Parse inline content (stops at NEWLINE via at_inline_end)
+        let parsed = parse_any_inline(p);
+        if parsed.is_absent() {
+            break;
+        }
+        after_hard_break = matches!(&parsed, Present(cm) if cm.kind(p) == MD_HARD_LINE);
+
+        // Per CommonMark §6.7: after a hard line break, leading spaces on the
+        // next line are ignored. First, run container continuation handling so
+        // block quote/list prefixes remain part of the same paragraph.
+        if after_hard_break {
+            let quote_depth = p.state().block_quote_depth;
+            if p.at(NEWLINE) || is_quote_blank_line_from_current(p, quote_depth) {
+                break;
+            }
+
+            if matches!(
+                handle_line_continuation(p, has_content, false),
+                InlineNewlineAction::Break
+            ) {
+                break;
+            }
+
+            while p.at(MD_TEXTUAL_LITERAL) && p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
+                p.consume_as_whitespace_trivia();
+            }
+        }
+
+        let inline_end: usize = p.cur_range().start().into();
+        has_content = inline_has_non_whitespace(p, inline_start, inline_end);
+    }
+
+    m.complete(p, MD_INLINE_ITEM_LIST);
+    p.set_emphasis_context(prev_emphasis_context);
+}
+
+fn is_quote_only_blank_line_from_source(p: &MarkdownParser, depth: usize) -> bool {
+    if depth == 0 {
+        return false;
+    }
+
+    let source = p.source().source_text();
+    let start: usize = p.cur_range().start().into();
+    if start >= source.len() {
+        return true;
+    }
+
+    // Scan up to 3 spaces/tabs before the first '>'
+    let mut idx = start;
+    let mut indent = 0usize;
+    while idx < source.len() {
+        match source.as_bytes()[idx] {
+            b' ' => {
+                indent += 1;
+                idx += 1;
+            }
+            b'\t' => {
+                indent += TAB_STOP_SPACES - (indent % TAB_STOP_SPACES);
+                idx += 1;
+            }
+            _ => break,
+        }
+        if indent > MAX_BLOCK_PREFIX_INDENT {
+            return false;
+        }
+    }
+
+    // Consume quote markers and optional single space after each
+    for _ in 0..depth {
+        if idx >= source.len() || source.as_bytes()[idx] != b'>' {
+            return false;
+        }
+        idx += 1;
+        if idx < source.len() {
+            let c = source.as_bytes()[idx];
+            if c == b' ' || c == b'\t' {
+                idx += 1;
+            }
+        }
+    }
+
+    // Skip trailing whitespace
+    while idx < source.len() {
+        match source.as_bytes()[idx] {
+            b' ' | b'\t' => idx += 1,
+            _ => break,
+        }
+    }
+
+    // Blank if line ends here or at newline
+    if idx >= source.len() {
+        return true;
+    }
+
+    matches!(source.as_bytes()[idx], b'\n' | b'\r')
+}
+
+/// Build an emphasis context for the current inline list and install it on the parser.
+/// Returns the previous context so it can be restored.
+fn set_inline_emphasis_context(p: &mut MarkdownParser) -> Option<EmphasisContext> {
+    let source_len = inline_list_source_len(p);
+    let source = p.source_after_current();
+    let inline_source = if source_len <= source.len() {
+        &source[..source_len]
+    } else {
+        source
+    };
+    let base_offset = u32::from(p.cur_range().start()) as usize;
+    // Create a reference checker closure that uses the parser's link reference definitions
+    let context = EmphasisContext::new(inline_source, base_offset, |label| {
+        p.has_link_reference_definition(label)
+    });
+    p.set_emphasis_context(Some(context))
+}
+
+// #region inline list length scanning
+
+/// Compute the byte length of the inline list starting at the current token.
+///
+/// Uses source positions rather than accumulated token text lengths so
+/// that trivia between tokens is included and the result always falls
+/// on a char boundary.
+fn inline_list_source_len(p: &mut MarkdownParser) -> usize {
+    let start: usize = p.cur_range().start().into();
+    p.lookahead(|p| {
+        let mut has_content = false;
+
+        loop {
+            if p.at(T![EOF]) {
+                break;
+            }
+
+            if p.at(NEWLINE) {
+                if scan_newline_in_inline_list(p, has_content) {
+                    break;
+                }
+                continue;
+            }
+
+            if has_content && p.at(MD_SETEXT_UNDERLINE_LITERAL) && allow_setext_heading(p) {
+                break;
+            }
+
+            if has_content && p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break(p) {
+                break;
+            }
+
+            if p.has_preceding_line_break() && at_block_interrupt(p) {
+                break;
+            }
+
+            if !p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
+                has_content = true;
+            }
+
+            p.bump(p.cur());
+        }
+
+        let end: usize = p.cur_range().start().into();
+        end.saturating_sub(start)
+    })
+}
+
+/// Handle a NEWLINE token during inline list length scanning.
+///
+/// Returns `true` if the scan should stop (paragraph boundary reached),
+/// `false` if scanning should continue to the next line.
+fn scan_newline_in_inline_list(p: &mut MarkdownParser, has_content: bool) -> bool {
+    if p.at_blank_line() {
+        p.bump(NEWLINE);
+        return true;
+    }
+
+    p.bump(NEWLINE);
+
+    let quote_depth = p.state().block_quote_depth;
+    if quote_depth > 0 && has_quote_prefix(p, quote_depth) {
+        let break_kind = classify_quote_break_after_newline(p, quote_depth);
+        if !matches!(break_kind, QuoteBreakKind::None) {
+            return true;
+        }
+        consume_quote_prefix_without_virtual(p, quote_depth);
+    }
+
+    if has_content && p.at(MD_SETEXT_UNDERLINE_LITERAL) && allow_setext_heading(p) {
+        return true;
+    }
+
+    if has_content && p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break(p) {
+        return true;
+    }
+
+    if quote_depth > 0 && p.at(R_ANGLE) && !has_quote_prefix(p, quote_depth) {
+        consume_partial_quote_prefix_lookahead(p, quote_depth);
+    }
+
+    if at_paragraph_break(p, has_content) {
+        return true;
+    }
+
+    let required_indent = p.state().list_item_required_indent;
+    if required_indent > 0 {
+        let indent = p.line_start_leading_indent();
+        if indent >= required_indent {
+            scan_list_indent(p, required_indent);
+
+            // After stripping list indent, re-check setext/thematic markers
+            // to mirror newline handling in the parse path. Without this,
+            // prescan would include indent bytes and stop one iteration later.
+            // We intentionally skip the heavier post-indent block-interrupt
+            // check here; the following non-NEWLINE pass still catches
+            // interrupts for emphasis-context length calculation.
+            if has_content
+                && (p.at(MD_SETEXT_UNDERLINE_LITERAL)
+                    || (p.at(MD_THEMATIC_BREAK_LITERAL)
+                        && is_dash_only_thematic_break_text(p.cur_text())))
+            {
+                return true;
+            }
+        } else if at_block_interrupt_after_indent(p) {
+            // CommonMark §5.2: at insufficient indent we keep scanning so
+            // the emphasis context sees lazy-continuation delimiters, but
+            // a sibling/parent list marker (or other block interrupt) at
+            // the next line still ends the paragraph and must stop the
+            // scan early — without this, deeply nested list benchmarks
+            // walk through every leading-whitespace token of every
+            // following line.
+            return true;
+        }
+    }
+
+    false
+}
+
+/// Lookahead: skip leading whitespace tokens on the current line and
+/// return whether the resulting position is a block interrupt or list
+/// marker. Used to short-circuit lazy-continuation scanning when the
+/// next line actually starts a new block.
+///
+/// Per CommonMark §5.2, a line indented 4+ columns *past the parent
+/// list marker* is paragraph text (lazy continuation), never a block
+/// interrupt — return false in that window. Lines below that threshold
+/// can still be sibling/parent list markers, so we keep walking and
+/// re-check, which is what restores the fast path for deeply nested
+/// lists where absolute indent is already large.
+fn at_block_interrupt_after_indent(p: &mut MarkdownParser) -> bool {
+    p.lookahead(|p| {
+        let lazy_threshold = p.state().list_item_marker_indent + INDENT_CODE_BLOCK_SPACES;
+        let mut indent = 0usize;
+        while p.at(MD_TEXTUAL_LITERAL) && p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
+            for c in p.cur_text().chars() {
+                match c {
+                    ' ' => indent += 1,
+                    '\t' => indent += TAB_STOP_SPACES - (indent % TAB_STOP_SPACES),
+                    _ => {}
+                }
+            }
+            if indent >= lazy_threshold {
+                return false;
+            }
+            p.bump(MD_TEXTUAL_LITERAL);
+        }
+        with_virtual_line_start(p, p.cur_range().start(), |p| {
+            if at_block_interrupt(p) || textual_looks_like_list_marker(p) {
+                return true;
+            }
+            // Mirror `parse_inline_item_list`'s break on non-1 ordered
+            // sibling markers: a marker still folded into `MD_TEXTUAL_LITERAL`
+            // would otherwise let the prescan walk past the paragraph boundary
+            // and leak emphasis delimiters from the next list item.
+            p.at(MD_TEXTUAL_LITERAL) && textual_starts_with_ordered_marker(p.cur_text())
+        })
+    })
+}
+
+/// Strip list-item indent tokens during inline list length scanning.
+///
+/// Consumes whitespace tokens up to `required_indent` columns, adding their
+/// byte lengths to `len`. Stops when the required indent is reached, a
+/// non-whitespace token is encountered, or consuming the next token would
+/// exceed the indent budget.
+fn scan_list_indent(p: &mut MarkdownParser, required_indent: usize) {
+    let mut consumed = 0usize;
+    while consumed < required_indent && p.at(MD_TEXTUAL_LITERAL) {
+        let text = p.cur_text();
+        if text.is_empty() || !text.chars().all(|c| c == ' ' || c == '\t') {
+            break;
+        }
+
+        let indent: usize = text
+            .chars()
+            .map(|c| if c == '\t' { TAB_STOP_SPACES } else { 1 })
+            .sum();
+
+        if consumed + indent > required_indent {
+            break;
+        }
+
+        consumed += indent;
+        p.bump(MD_TEXTUAL_LITERAL);
+    }
+}
+
+// #endregion
+
+fn line_starts_with_fence(p: &mut MarkdownParser) -> bool {
+    if !p.at_line_start() {
+        return false;
+    }
+
+    p.lookahead(|p| {
+        if p.line_start_leading_indent() > MAX_BLOCK_PREFIX_INDENT {
+            return false;
+        }
+        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);
+        let rest = p.source_after_current();
+        let Some((fence_char, _len)) = fenced_code_block::detect_fence(rest) else {
+            return false;
+        };
+        if fence_char == '`' {
+            return !info_string_has_backtick(p);
+        }
+        true
+    })
+}
+
+fn consume_partial_quote_prefix(p: &mut MarkdownParser, depth: usize) -> bool {
+    let mut consumed = 0usize;
+    while consumed < depth && p.at(R_ANGLE) {
+        // Emit as MdQuotePrefix (same structure as Phase 1 full quote prefixes)
+        let prefix_m = p.start();
+
+        // Empty pre-marker indent list
+        let indent_list_m = p.start();
+        indent_list_m.complete(p, MD_QUOTE_INDENT_LIST);
+
+        // The `>` marker
+        p.bump(R_ANGLE);
+
+        // Optional post-marker space
+        if p.at(MD_TEXTUAL_LITERAL) {
+            let text = p.cur_text();
+            if text == " " || text == "\t" {
+                p.bump_remap(MD_QUOTE_POST_MARKER_SPACE);
+            }
+        }
+
+        prefix_m.complete(p, MD_QUOTE_PREFIX);
+        consumed += 1;
+    }
+    consumed > 0
+}
+
+fn consume_partial_quote_prefix_lookahead(p: &mut MarkdownParser, depth: usize) -> bool {
+    let mut consumed = 0usize;
+    while consumed < depth && p.at(R_ANGLE) {
+        p.bump(R_ANGLE);
+        if p.at(MD_TEXTUAL_LITERAL) {
+            let text = p.cur_text();
+            if text == " " || text == "\t" {
+                p.bump(MD_TEXTUAL_LITERAL);
+            }
+        }
+        consumed += 1;
+    }
+    consumed > 0
+}
+
+/// Check if we're at a block-level construct that can interrupt a paragraph.
+///
+/// Per CommonMark, these constructs can interrupt paragraphs:
+/// - ATX headings (# followed by space or EOL)
+/// - Fenced code blocks (``` or ~~~)
+/// - Block quotes (>)
+/// - Thematic breaks (---, ***, ___)
+/// - List items (-, *, +, or ordered markers) - with restrictions
+/// - HTML blocks (certain types)
+///
+/// Note: Setext headings and indented code blocks do NOT interrupt paragraphs.
+/// Also, lines with 4+ spaces of indentation cannot start these constructs
+/// (they would be indented code blocks instead).
+///
+/// ## List Interruption Rules (CommonMark §5.2)
+///
+/// - Bullet lists can interrupt paragraphs if item has content OR marker is followed by blank line
+/// - Ordered lists can interrupt paragraphs ONLY if starting with `1` AND not empty
+pub(crate) fn at_block_interrupt(p: &mut MarkdownParser) -> bool {
+    // Per CommonMark, lines indented 4+ spaces cannot start block constructs
+    // that interrupt paragraphs - they would be indented code blocks.
+    // Tabs count as 4 spaces per CommonMark §2.2.
+    if p.line_start_leading_indent() >= INDENT_CODE_BLOCK_SPACES {
+        // Inside list items, list markers at the current indent can start
+        // nested lists. Ordered markers still need to satisfy §5.2.
+        if p.state().list_nesting_depth > 0 || p.state().list_item_required_indent > 0 {
+            if at_bullet_list_item(p) {
+                return true;
+            }
+            if at_order_list_item(p) && can_ordered_marker_interrupt_paragraph(p) {
+                return true;
+            }
+            // Siblings sit at the enclosing item's marker indent, which can
+            // fall below its content indent when the marker is followed by more
+            // than one space or a tab. Check there too, so they aren't absorbed
+            // as lazy paragraph continuation.
+            if at_sibling_list_marker(p) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    // ATX heading: # at line start (must have space/tab after per CommonMark §4.2)
+    // Use checkpoint to look ahead and verify it's a valid heading
+    if at_header(p) {
+        return is_valid_atx_heading_start(p);
+    }
+
+    // Fenced code block (``` or ~~~) - lexer already ensures line start
+    if at_fenced_code_block(p) {
+        return true;
+    }
+
+    // Block quote (>)
+    if at_quote(p) {
+        return true;
+    }
+
+    // Thematic break (---, ***, ___) - lexer already ensures line start
+    if at_thematic_break_block(p) {
+        return true;
+    }
+
+    // Bullet list item (-, *, +)
+    // Per CommonMark §5.2: bullet lists can interrupt paragraphs only if the
+    // item has content (non-empty). Empty markers cannot interrupt paragraphs.
+    // When inside a list, we also need to check for list items at ANY indent
+    // (not just at the current context's indent) because a less-indented list
+    // marker would end the current list item and start a sibling/parent item.
+    if at_bullet_list_item(p) || at_bullet_list_item_at_any_indent(p) {
+        let in_list = p.state().list_nesting_depth > 0;
+        if in_list || can_bullet_interrupt_paragraph(p) {
+            return true;
+        }
+    }
+
+    // Ordered markers may interrupt paragraphs only when they start with `1`
+    // and are non-empty (§5.2). In list context, a marker physically before
+    // required_indent is a sibling/parent boundary and is allowed.
+    if (at_order_list_item(p) || at_order_list_item_at_any_indent(p))
+        && can_ordered_marker_interrupt_paragraph(p)
+    {
+        return true;
+    }
+
+    // HTML block (type 7 does not interrupt paragraphs)
+    if at_html_block_interrupt(p) {
+        return true;
+    }
+
+    false
+}
+
+/// Check if the current token looks like a list marker when lexed as textual content.
+///
+/// Inside inline content, list markers like `- ` are lexed as MD_TEXTUAL_LITERAL.
+/// This function checks if a textual token at line start looks like it would be
+/// a list marker in block context.
+fn textual_looks_like_list_marker(p: &mut MarkdownParser) -> bool {
+    if !p.at(MD_TEXTUAL_LITERAL) {
+        return false;
+    }
+
+    let text = p.cur_text();
+
+    // Bullet marker: single -, *, or + followed by space/tab or EOF
+    if text == "-" || text == "*" || text == "+" {
+        // Check if followed by space, tab, or at end of line
+        return p.lookahead(|p| {
+            p.bump(MD_TEXTUAL_LITERAL);
+            if p.at(T![EOF]) || p.at(NEWLINE) {
+                return true;
+            }
+            if p.at(MD_TEXTUAL_LITERAL) {
+                let next = p.cur_text();
+                return next.starts_with(' ') || next.starts_with('\t');
+            }
+            false
+        });
+    }
+
+    // Ordered marker: per CommonMark §5.2, only ordered lists starting with 1
+    // can interrupt paragraphs. Check if text is "1." or "1)" pattern.
+    if let Some(rest) = text.strip_prefix('1') {
+        // "1." or "1)" followed by space (the space might be in next token)
+        if rest == "." || rest == ")" {
+            return p.lookahead(|p| {
+                p.bump(MD_TEXTUAL_LITERAL);
+                if p.at(T![EOF]) || p.at(NEWLINE) {
+                    return true;
+                }
+                if p.at(MD_TEXTUAL_LITERAL) {
+                    let next = p.cur_text();
+                    return next.starts_with(' ') || next.starts_with('\t');
+                }
+                false
+            });
+        }
+        // "1. " or "1) " all in one token
+        if rest.starts_with(". ")
+            || rest.starts_with(".\t")
+            || rest.starts_with(") ")
+            || rest.starts_with(")\t")
+        {
+            return true;
+        }
+    }
+
+    false
+}
+
+/// Return true when the current ordered marker may interrupt a paragraph.
+///
+/// CommonMark §5.2 requires ordered paragraph interrupters to start with `1`
+/// and be non-empty. Inside a list, physical indent below `required_indent`
+/// means the marker is a sibling/parent boundary instead of an interrupter.
+fn can_ordered_marker_interrupt_paragraph(p: &mut MarkdownParser) -> bool {
+    let in_list = p.state().list_nesting_depth > 0;
+    let required_indent = p.state().list_item_required_indent;
+    let physical_indent = physical_line_start_indent(p);
+    let is_sibling_or_parent = in_list && physical_indent < required_indent;
+
+    if is_sibling_or_parent {
+        return true;
+    }
+
+    ordered_marker_starts_with_one_after_whitespace(p)
+        && !is_ordered_marker_empty_after_whitespace(p)
+}
+
+/// Like [`is_ordered_list_starts_with_one`], but skips leading whitespace.
+fn ordered_marker_starts_with_one_after_whitespace(p: &mut MarkdownParser) -> bool {
+    if p.at(MD_TEXTUAL_LITERAL) {
+        let trimmed = p.cur_text().trim_start_matches([' ', '\t']);
+        if let Some(rest) = trimmed
+            .strip_prefix("1.")
+            .or_else(|| trimmed.strip_prefix("1)"))
+        {
+            return rest.is_empty() || rest.starts_with([' ', '\t']);
+        }
+    }
+    p.lookahead(|p| {
+        while p.at(MD_TEXTUAL_LITERAL) && p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
+            p.bump(MD_TEXTUAL_LITERAL);
+        }
+        is_ordered_list_starts_with_one(p)
+    })
+}
+
+/// Like [`is_empty_list_item`], but skips leading whitespace.
+fn is_ordered_marker_empty_after_whitespace(p: &mut MarkdownParser) -> bool {
+    p.lookahead(|p| {
+        while p.at(MD_TEXTUAL_LITERAL) && p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
+            p.bump(MD_TEXTUAL_LITERAL);
+        }
+        is_empty_list_item(p)
+    })
+}
+
+/// Count physical leading columns, ignoring `virtual_line_start`.
+///
+/// This is needed after indentation has already been emitted as CST nodes.
+/// Tabs expand to the next multiple of `TAB_STOP_SPACES`.
+fn physical_line_start_indent(p: &MarkdownParser) -> usize {
+    let source = p.source().source_text();
+    let pos: usize = p.cur_range().start().into();
+    let line_start = source[..pos].rfind('\n').map_or(0, |idx| idx + 1);
+    let mut col = 0usize;
+    for c in source[line_start..].chars() {
+        match c {
+            ' ' => col += 1,
+            '\t' => col += TAB_STOP_SPACES - (col % TAB_STOP_SPACES),
+            _ => break,
+        }
+    }
+    col
+}
+
+/// Check if an ordered list marker starts with the number 1.
+///
+/// Per CommonMark §5.2: "In order to solve of an ambiguity in the spec,
+/// only ordered lists starting with 1 can interrupt paragraphs."
+///
+/// This prevents accidental list creation from wrapped lines like:
+/// "The number of windows is 14. The number of doors is 6."
+pub(crate) fn is_ordered_list_starts_with_one(p: &mut MarkdownParser) -> bool {
+    // Raw ordered list marker token: text is the full marker (e.g. "1.", "10.").
+    if p.at(MD_ORDERED_LIST_MARKER) {
+        let text = p.cur_text();
+        return text == "1." || text == "1)";
+    }
+    // Textual ordered marker (e.g. inside an inline list source span): the
+    // lexer keeps the digits + delimiter inside MD_TEXTUAL_LITERAL. Accept
+    // an exact `1.` / `1)` prefix optionally followed by whitespace or EOL.
+    if p.at(MD_TEXTUAL_LITERAL) {
+        let text = p.cur_text();
+        if let Some(rest) = text.strip_prefix("1.").or_else(|| text.strip_prefix("1)")) {
+            return rest.is_empty() || rest.starts_with([' ', '\t']);
+        }
+    }
+    false
+}
+
+/// Check for a bullet list item at any valid top-level indent (0-3 spaces).
+///
+/// This is used for detecting paragraph interruption when we're inside a nested
+/// context (like a list item) but need to detect list markers at any level,
+/// not just at the current context's indent level.
+fn at_bullet_list_item_at_any_indent(p: &mut MarkdownParser) -> bool {
+    p.lookahead(|p| {
+        if !p.at_line_start() {
+            return false;
+        }
+
+        // Top-level list items can have 0-3 spaces of leading indent
+        let indent = p.line_start_leading_indent();
+        if indent > MAX_BLOCK_PREFIX_INDENT {
+            return false;
+        }
+
+        // Skip leading whitespace tokens
+        while p.at(MD_TEXTUAL_LITERAL) && p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
+            p.bump(MD_TEXTUAL_LITERAL);
+        }
+
+        // Check for -, *, or + marker
+        if p.at(MD_SETEXT_UNDERLINE_LITERAL) {
+            let trimmed = p.cur_text().trim_matches(|c| c == ' ' || c == '\t');
+            if trimmed != "-" {
+                return false;
+            }
+        } else if !p.at(T![-]) && !p.at(T![*]) && !p.at(T![+]) {
+            return false;
+        }
+
+        if p.at(MD_SETEXT_UNDERLINE_LITERAL) {
+            p.bump_remap(T![-]);
+        } else {
+            p.bump(p.cur());
+        }
+        marker_followed_by_whitespace_or_eol(p)
+    })
+}
+
+/// Check for an ordered list item at any valid top-level indent (0-3 spaces).
+///
+/// This is used for detecting paragraph interruption when we're inside a nested
+/// context (like a list item) but need to detect list markers at any level.
+fn at_order_list_item_at_any_indent(p: &mut MarkdownParser) -> bool {
+    p.lookahead(|p| {
+        if !p.at_line_start() {
+            return false;
+        }
+
+        // Top-level list items can have 0-3 spaces of leading indent
+        let indent = p.line_start_leading_indent();
+        if indent > MAX_BLOCK_PREFIX_INDENT {
+            return false;
+        }
+
+        // Skip leading whitespace tokens
+        while p.at(MD_TEXTUAL_LITERAL) && p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
+            p.bump(MD_TEXTUAL_LITERAL);
+        }
+
+        // Check for ordered list marker (lexer produces MD_ORDERED_LIST_MARKER)
+        p.at(MD_ORDERED_LIST_MARKER)
+    })
+}
+
+fn at_order_list_item_textual(p: &mut MarkdownParser) -> bool {
+    p.lookahead(|p| {
+        if !p.at_line_start() {
+            return false;
+        }
+
+        let indent = p.line_start_leading_indent();
+        let base_indent = if p.state().virtual_line_start == Some(p.cur_range().start())
+            && p.state().list_item_required_indent > 0
+        {
+            0
+        } else {
+            p.state().list_item_required_indent
+        };
+
+        if base_indent == 0 {
+            if indent > MAX_BLOCK_PREFIX_INDENT {
+                return false;
+            }
+        } else if indent < base_indent || indent > base_indent + MAX_BLOCK_PREFIX_INDENT {
+            return false;
+        }
+
+        while p.at(MD_TEXTUAL_LITERAL) && p.cur_text().chars().all(|c| c == ' ' || c == '\t') {
+            p.bump(MD_TEXTUAL_LITERAL);
+        }
+
+        p.at(MD_TEXTUAL_LITERAL) && textual_starts_with_ordered_marker(p.cur_text())
+    })
+}
+
+/// Check if a bullet list item can interrupt a top-level paragraph.
+///
+/// Per CommonMark §5.2: "A bullet list can interrupt a paragraph only if
+/// it starts with a non-empty item (that is, a list item that contains
+/// some non-blank character)."
+///
+/// This means empty markers (marker followed by only whitespace/newline)
+/// cannot interrupt paragraphs, regardless of what follows.
+fn can_bullet_interrupt_paragraph(p: &mut MarkdownParser) -> bool {
+    let checkpoint = p.checkpoint();
+
+    // Bump the bullet marker (-, *, or +)
+    if p.at(T![-]) {
+        p.bump(T![-]);
+    } else if p.at(T![*]) {
+        p.bump(T![*]);
+    } else if p.at(T![+]) {
+        p.bump(T![+]);
+    } else {
+        p.rewind(checkpoint);
+        return false;
+    }
+
+    if !marker_followed_by_whitespace_or_eol(p) {
+        p.rewind(checkpoint);
+        return false;
+    }
+
+    // Check what follows the marker
+    // Per CommonMark §5.2: "A bullet list can interrupt a paragraph only if
+    // it starts with a non-empty item (that is, a list item that contains
+    // some non-blank character)."
+    let result = if p.at(T![EOF]) {
+        // Empty item at EOF - cannot interrupt
+        false
+    } else if p.at(NEWLINE) {
+        // Empty item (marker + newline) - cannot interrupt paragraphs
+        false
+    } else if p.at(MD_TEXTUAL_LITERAL) && is_whitespace_only(p.cur_text()) {
+        // Skip all whitespace tokens after marker
+        while p.at(MD_TEXTUAL_LITERAL) && is_whitespace_only(p.cur_text()) {
+            p.bump(MD_TEXTUAL_LITERAL);
+        }
+        // If only whitespace followed by newline/EOF, item is empty and cannot interrupt
+        !(p.at(NEWLINE) || p.at(T![EOF]))
+    } else {
+        // Has content after marker - can interrupt
+        true
+    };
+
+    p.rewind(checkpoint);
+    result
+}
+
+/// Check if the current list item is empty (no content after marker).
+///
+/// Per CommonMark §5.2: "an empty list item cannot interrupt a paragraph."
+///
+/// Uses lookahead to check if only whitespace/newline follows the marker.
+fn is_empty_list_item(p: &mut MarkdownParser) -> bool {
+    let checkpoint = p.checkpoint();
+
+    // Bump the list marker
+    if p.at(MD_ORDERED_LIST_MARKER) {
+        p.bump(MD_ORDERED_LIST_MARKER);
+    } else if p.at(T![-]) {
+        p.bump(T![-]);
+    } else if p.at(T![*]) {
+        p.bump(T![*]);
+    } else if p.at(T![+]) {
+        p.bump(T![+]);
+    } else {
+        p.rewind(checkpoint);
+        return false;
+    }
+
+    if !marker_followed_by_whitespace_or_eol(p) {
+        p.rewind(checkpoint);
+        return false;
+    }
+
+    // Check what follows the marker
+    if p.at(MD_TEXTUAL_LITERAL) && is_whitespace_only(p.cur_text()) {
+        p.bump(MD_TEXTUAL_LITERAL);
+    }
+
+    // Empty if: EOF or NEWLINE after optional whitespace
+    let is_empty = p.at(T![EOF]) || p.at(NEWLINE);
+
+    p.rewind(checkpoint);
+    is_empty
+}
+
+pub(crate) fn is_whitespace_only(text: &str) -> bool {
+    !text.is_empty() && text.chars().all(|c| c == ' ' || c == '\t')
+}
+
+/// Check if the current position has too many hashes for an ATX heading (>6).
+///
+/// Returns `Some((range, count))` if there are >6 hashes, `None` otherwise.
+/// This is used to emit a diagnostic BEFORE `try_parse` which would lose it on rewind.
+fn check_too_many_hashes(p: &mut MarkdownParser) -> Option<(biome_rowan::TextRange, usize)> {
+    p.lookahead(|p| {
+        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);
+
+        if !p.at(T![#]) {
+            return None;
+        }
+
+        // The lexer emits all consecutive `#` as a single HASH token.
+        // Get the count from token text length.
+        let range = p.cur_range();
+        let count = p.cur_text().len();
+
+        if count > MAX_ATX_HEADING_LEVEL {
+            Some((range, count))
+        } else {
+            None
+        }
+    })
+}
+
+/// Check if we're at a valid ATX heading start (1-6 `#` followed by space or EOL).
+/// Uses lookahead to verify without consuming tokens.
+fn is_valid_atx_heading_start(p: &mut MarkdownParser) -> bool {
+    p.lookahead(|p| {
+        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);
+
+        // The lexer emits all consecutive `#` as a single HASH token.
+        // Count hash characters from the token's text length.
+        if !p.at(T![#]) {
+            return false;
+        }
+
+        let hash_count = p.cur_text().len();
+
+        // Too many hashes - not a valid heading (must be 1-6)
+        if hash_count > MAX_ATX_HEADING_LEVEL {
+            return false;
+        }
+
+        p.bump(T![#]);
+
+        // Check if followed by space, tab, or EOL/EOF per CommonMark §4.2
+        // In Markdown, whitespace is significant and included in token text.
+        let text = p.cur_text();
+        p.at(T![EOF])
+            || p.has_preceding_line_break()
+            || text.starts_with(' ')
+            || text.starts_with('\t')
+    })
+}
+
+/// Parse any inline element.
+///
+/// Dispatches to the appropriate inline parser based on the current token.
+pub(crate) fn parse_any_inline(p: &mut MarkdownParser) -> ParsedSyntax {
+    inline::parse_any_inline(p)
+}
+
+/// Parse a textual inline element.
+///
+/// Grammar: MdTextual = value: 'md_textual_literal'
+///
+/// For now, we treat any non-EOF token as textual content to ensure
+/// the paragraph parser makes progress. In later prompts, we'll add
+/// proper handling for inline elements like emphasis, links, etc.
+pub(crate) fn parse_textual(p: &mut MarkdownParser) -> ParsedSyntax {
+    if p.at(T![EOF]) {
+        return Absent;
+    }
+    // A construct token that turned out to be plain text (failed emphasis
+    // marker, unmatched bracket, ...) would become a one-character node and
+    // split the surrounding prose. Re-lex it as plain text so it merges with
+    // the characters that follow it.
+    if p.at_ts(MERGES_WITH_FOLLOWING_TEXT) {
+        p.re_lex_textual_fallback();
+    }
+    let m = p.start();
+    // Remap any token to MD_TEXTUAL_LITERAL so the syntax factory accepts it.
+    // This is necessary because tokens like L_PAREN, R_PAREN, etc. are lexed
+    // as their specific token kinds, but MdTextual expects MD_TEXTUAL_LITERAL.
+    p.bump_remap(MD_TEXTUAL_LITERAL);
+    Present(m.complete(p, MD_TEXTUAL))
+}
+
+/// Construct tokens that, once they fail to open a construct, read as plain
+/// text and can merge with the characters after them via
+/// [MarkdownParser::re_lex_textual_fallback].
+///
+/// Backtick and tilde tokens are deliberately absent: they carry a full
+/// delimiter sequence (like ```` `` ````) whose length drives code span
+/// matching, so re-splitting them would change how later code spans pair up.
+const MERGES_WITH_FOLLOWING_TEXT: TokenSet<MarkdownSyntaxKind> = token_set![
+    T![*],
+    UNDERSCORE,
+    BANG,
+    L_BRACK,
+    R_BRACK,
+    L_ANGLE,
+    R_ANGLE,
+    T!['('],
+    T![')'],
+    COLON,
+    T![-],
+    T![+],
+    T![#],
+];
+
+/// Attempt to parse some input with the given parsing function. If parsing
+/// succeeds, `Ok` is returned with the result of the parse and the state is
+/// preserved. If parsing fails, this function rewinds the parser back to
+/// where it was before attempting the parse and the `Err` value is returned.
+#[must_use = "The result of try_parse contains information about whether the parse succeeded and should not be ignored"]
+pub(crate) fn try_parse<T, E>(
+    p: &mut MarkdownParser,
+    func: impl FnOnce(&mut MarkdownParser) -> Result<T, E>,
+) -> Result<T, E> {
+    let checkpoint = p.checkpoint();
+
+    let res = func(p);
+
+    if res.is_err() {
+        p.rewind(checkpoint);
+    }
+
+    res
+}
